create table if not exists app.automation_notifications (id uuid primary key default gen_random_uuid(), owner_id uuid not null references app.profiles(id) on delete cascade, run_id uuid references app.automation_runs(id) on delete cascade, notification_key text not null, message text not null, created_at timestamptz not null default now(), unique (owner_id, notification_key));
create table if not exists app.automation_dead_letters (id uuid primary key default gen_random_uuid(), owner_id uuid not null references app.profiles(id) on delete cascade, event_id text not null, event_name text not null, payload_metadata jsonb not null default '{}', reason text not null, created_at timestamptz not null default now());
alter table app.automation_notifications enable row level security; alter table app.automation_dead_letters enable row level security;
create policy automation_notifications_owner on app.automation_notifications for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy automation_dead_letters_owner on app.automation_dead_letters for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
